def ref(n):
    return REFERENCES.get(n)


def short(n):
    """Compact label 'FirstAuthor (Year)' for inline citation; '' if unknown."""
    import re
    r = REFERENCES.get(n)
    if not r:
        return f"[ref {n}]"
    cite = r.get("cite", "")
    author = cite.split(",")[0].strip() if cite else f"ref{n}"
    ym = re.search(r"\b(19|20)\d{2}\b", cite)
    return f"{author} ({ym.group(0)})" if ym else author
